package store

// User is one row of the users table.
type User struct {
	ID    string
	Email string
}

var users = map[string]User{}

// FindUser returns the user with the given id, or nil when no user has that
// id.
func FindUser(id string) *User {
	u, ok := users[id]
	if !ok {
		return nil
	}
	return &u
}

